WITH filtered AS (SELECT *, ROUND(balance, 0) AS balance_rounded FROM accounts WHERE opened_date >= DATE '2023-06-25' AND status IS NOT NULL), matched AS (SELECT e.*, sub.id AS subscription_id, sub.plan, sub.monthly_fee FROM filtered e LEFT JOIN subscriptions sub ON e.customer_id = sub.customer_id AND e.opened_date >= sub.start_date AND e.opened_date < sub.end_date + INTERVAL 7 DAYS), with_windows AS (SELECT id, customer_id, account_type, balance, balance_rounded, subscription_id, STDDEV_SAMP(monthly_fee) OVER (PARTITION BY plan) AS plan_stddev_samp_monthly_fee, CUME_DIST() OVER (PARTITION BY plan ORDER BY subscription_id) AS subscription_id_cume_dist, STDDEV_SAMP(balance_rounded) OVER (PARTITION BY account_type) AS account_type_stddev_samp_balance_rounded FROM matched WHERE status NOT IN ('OPEN', 'CLOSED')), with_windows_accounts AS (SELECT id, customer_id, balance, balance_rounded, subscription_id, account_type_stddev_samp_balance_rounded, COUNT(balance) OVER w_part AS account_type_count_balance, MAX(subscription_id) OVER (PARTITION BY customer_id) AS customer_id_max_subscription_id, AVG(subscription_id) OVER w_grp AS subscription_id_avg_2 FROM with_windows WINDOW w_part AS (PARTITION BY account_type), w_grp AS (ORDER BY subscription_id_cume_dist, id, subscription_id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)), metrics AS (SELECT id, customer_id, balance, balance_rounded, subscription_id, customer_id_max_subscription_id, LEAD(balance_rounded, 2) OVER (PARTITION BY customer_id ORDER BY balance, id, subscription_id) AS next_balance_rounded, SUM(account_type_count_balance) OVER (PARTITION BY customer_id ORDER BY customer_id_max_subscription_id, id, subscription_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_account_type_count_balance, AVG(subscription_id_avg_2) OVER (PARTITION BY customer_id ORDER BY balance, id, subscription_id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS subscription_id_avg_2_avg_2_prior, PERCENT_RANK() OVER (PARTITION BY customer_id ORDER BY account_type_stddev_samp_balance_rounded DESC) AS account_type_stddev_samp_balance_rounded_percent_rank, NTILE(10) OVER (PARTITION BY customer_id ORDER BY subscription_id_avg_2 DESC, id, subscription_id) AS subscription_id_avg_2_bucket FROM with_windows_accounts) SELECT s.id, s.customer_id, s.subscription_id, s.customer_id_max_subscription_id, s.next_balance_rounded, s.running_account_type_count_balance, s.subscription_id_avg_2_avg_2_prior, s.account_type_stddev_samp_balance_rounded_percent_rank, s.subscription_id_avg_2_bucket, (SELECT MIN(s2.monthly_fee) FROM subscriptions s2 WHERE s2.customer_id = s.customer_id) AS min_subscription_monthly_fee FROM metrics s;
